#nullable enable
using Microsoft.Extensions.Logging;

namespace Tracto.Desktop.Actions.Handlers;

/// <summary>
/// Activates a control or window so subsequent input goes to it.
/// Generated by the capture engine for Focus events.
///
/// Action name: focus
/// Inputs:
///   window  (string, optional) — window title hint
///   target  (string, optional) — control name / automation ID (informational; used for logging)
/// Outputs:
///   windowHandle (string)
/// </summary>
public sealed class FocusHandler : IActionHandler
{
    private readonly ILogger<FocusHandler> _logger;

    public string ActionName => "focus";

    public FocusHandler(ILogger<FocusHandler> logger) => _logger = logger;

    public async Task<ActionResult> ExecuteAsync(ActionContext ctx)
    {
        var window = ctx.GetString("window");
        var target = ctx.GetString("target");

        if (string.IsNullOrWhiteSpace(window))
        {
            _logger.LogDebug("focus: no window specified (target={Target}) — no-op", target ?? "(none)");
            return ActionResult.Ok();
        }

        var hwnd = NativeMethods.FindWindowByTitle(window);
        if (hwnd == IntPtr.Zero)
        {
            _logger.LogWarning("focus: window '{Window}' not found", window);
            return ActionResult.Ok(new Dictionary<string, object?> { ["windowHandle"] = "0" });
        }

        NativeMethods.SetForegroundWindow(hwnd);
        await Task.Delay(200, ctx.CancellationToken);

        _logger.LogInformation("focus: window '{Window}' ({Handle:X}), target='{Target}'",
            window, hwnd, target ?? string.Empty);
        return ActionResult.Ok(new Dictionary<string, object?>
            { ["windowHandle"] = hwnd.ToString("X") });
    }
}
